import { preprocess } from './preprocess.js';
import { generateAISDKCompletions, streamAISDKCompletions, generateAISDKCode, } from './models.js';
export default class LLMScraper {
    client;
    constructor(client) {
        this.client = client;
        this.client = client;
    }
    async run(page, output, options) {
        const preprocessed = await preprocess(page, options);
        return generateAISDKCompletions(this.client, preprocessed, output, options);
    }
    async stream(page, output, options) {
        const preprocessed = await preprocess(page, options);
        return streamAISDKCompletions(this.client, preprocessed, output, options);
    }
    // Generate scraping code instead of data
    async generate(page, output, options) {
        const preprocessed = await preprocess(page, options);
        return generateAISDKCode(this.client, preprocessed, output, options);
    }
}
